from rules import amount


def solve(data):
    balances = dict(data.get('opening', {}))
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue
        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)
        revision = event.get('revision', 0)
        previous = winners.get(key)
        if previous is None or revision >= previous[0]:
            winners[key] = (revision, position, event)

    for _, _, event in winners.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        value = amount(event, data['rounding'])
        if event.get('kind') == 'refund':
            value = -value
        balances[key] += value

    return {'balances': balances}

def _round_ratio(numerator, denominator, mode):
    quotient, remainder = divmod(numerator, denominator)
    if mode == 'floor':
        return quotient
    if remainder * 2 >= denominator:
        return quotient + 1
    return quotient


def amount(event, mode):
    price_quantity = event['price'] * event.get('quantity', 1)
    discount = max(0, min(10000, event.get('discount_bp', 0)))
    net = _round_ratio(price_quantity * (10000 - discount), 10000, mode)
    tax = _round_ratio(net * event.get('tax_bp', 0), 10000, mode)
    return net + tax
